function calcular(datos) {
  var dia = function (iso) { return new Date(Date.parse(iso) - 5 * 3600 * 1000).toISOString().slice(0, 10); };
  var N = 365;
  var pedidos = (datos && datos.tablas && datos.tablas.pedidos) || [];
  var validos = { confirmado: true, enviado: true, entregado: true, novedad: true };
  var etiquetas = [];
  for (var i = N - 1; i >= 0; i--) {
    var iso = new Date(Date.parse(datos.hoy) - i * 86400000).toISOString();
    etiquetas.push(dia(iso));
  }
  var conteo = {};
  for (var k = 0; k < etiquetas.length; k++) { conteo[etiquetas[k]] = 0; }
  for (var p = 0; p < pedidos.length; p++) {
    var ped = pedidos[p];
    if (!ped || !validos[ped.estado] || !ped.creado) continue;
    var d = dia(ped.creado);
    if (d in conteo) { conteo[d] += 1; }
  }
  var serie = [];
  var total = 0;
  for (var j = 0; j < etiquetas.length; j++) {
    var e = etiquetas[j];
    var v = conteo[e] || 0;
    total += v;
    serie.push({ etiqueta: e, valor: v });
  }
  return { valor: total, unidad: "pedidos", serie: serie, nota: "Cuenta pedidos confirmados, enviados, entregados y con novedad de los ultimos 365 dias por dia en hora de Bogota." };
}

