function consultar(datos) {
  var dia = function (iso) { return new Date(Date.parse(iso) - 5 * 3600 * 1000).toISOString().slice(0, 10); };
  var fmt = function (iso) { return new Date(Date.parse(iso) - 5 * 3600 * 1000).toISOString().slice(0, 16).replace("T", " "); };
  var tablas = (datos && datos.tablas) || {};
  var pedidos = tablas.pedidos || [];
  var clientes = tablas.clientes || [];
  var mapaClientes = {};
  for (var i = 0; i < clientes.length; i++) {
    var c = clientes[i];
    if (c && c.id) mapaClientes[c.id] = c.nombre || c.id;
  }
  var hoyDia = dia(datos.hoy);
  var limiteDia = dia(new Date(Date.parse(datos.hoy) - 7 * 86400000).toISOString());
  var filtrados = [];
  for (var j = 0; j < pedidos.length; j++) {
    var p = pedidos[j];
    if (!p || p.estado !== "novedad" || !p.creado) continue;
    var d = dia(p.creado);
    if (d <= limiteDia) continue;
    if (d > hoyDia) continue;
    filtrados.push(p);
  }
  filtrados.sort(function (a, b) { return Date.parse(b.creado) - Date.parse(a.creado); });
  var filas = [];
  var n = filtrados.length > 200 ? 200 : filtrados.length;
  for (var k = 0; k < n; k++) {
    var q = filtrados[k];
    var nombreCliente = mapaClientes[q.clienteId] || null;
    if (!nombreCliente && q.clienteId) nombreCliente = q.clienteId;
    filas.push({
      numero: q.numero != null ? q.numero : null,
      fecha: fmt(q.creado),
      cliente: nombreCliente,
      ciudad: q.ciudad || null,
      total: typeof q.total === "number" ? q.total : null,
      estado: q.estado
    });
  }
  return filas;
}

