const dia = (iso) => new Date(Date.parse(iso) - 5 * 3600 * 1000).toISOString().slice(0, 10);
function calcular(datos) {
  var N = 60;
  var hoyDia = dia(datos.hoy);
  var limite = dia(new Date(Date.parse(datos.hoy) - N * 86400000).toISOString());
  var pedidos = (datos.tablas && datos.tablas.pedidos) || [];
  var conteo = {};
  for (var i = 0; i < pedidos.length; i++) {
    var p = pedidos[i];
    if (p.estado !== "confirmado" && p.estado !== "enviado" && p.estado !== "entregado" && p.estado !== "novedad") continue;
    if (!p.creado) continue;
    var d = dia(p.creado);
    if (!(d > limite && d <= hoyDia)) continue;
    var c = p.clienteId;
    conteo[c] = (conteo[c] || 0) + 1;
  }
  var conVenta = 0;
  var conMasDeUna = 0;
  for (var k in conteo) {
    if (Object.prototype.hasOwnProperty.call(conteo, k)) {
      conVenta += 1;
      if (conteo[k] > 1) conMasDeUna += 1;
    }
  }
  var porc = conVenta === 0 ? 0 : (conMasDeUna / conVenta) * 100;
  porc = Math.round(porc * 10) / 10;
  return {
    valor: porc,
    unidad: "%",
    nota: "Porcentaje sobre " + conVenta + " clientes con al menos una venta en los últimos 60 días; ventas = confirmado, enviado, entregado y novedad."
  };
}

