function calcular(datos) {
  const dia = (iso) => new Date(Date.parse(iso) - 5 * 3600 * 1000).toISOString().slice(0, 10);
  const N = 365;
  const hoyDia = dia(datos.hoy);
  const limite = dia(new Date(Date.parse(datos.hoy) - N * 86400000).toISOString());
  const esVenta = (e) => e === 'confirmado' || e === 'enviado' || e === 'entregado' || e === 'novedad';
  const pedidos = (datos.tablas && datos.tablas.pedidos) || [];
  const porProd = {};
  let total = 0;
  for (let i = 0; i < pedidos.length; i++) {
    const p = pedidos[i];
    if (!esVenta(p.estado)) continue;
    if (!p.creado) continue;
    const d = dia(p.creado);
    if (!(d > limite && d <= hoyDia)) continue;
    const items = p.items || [];
    for (let j = 0; j < items.length; j++) {
      const it = items[j];
      const cant = Number(it.cantidad) || 0;
      if (cant <= 0) continue;
      const key = it.productoId || it.nombre || 'desconocido';
      if (!porProd[key]) porProd[key] = { etiqueta: it.nombre || String(key), valor: 0 };
      if (it.nombre) porProd[key].etiqueta = it.nombre;
      porProd[key].valor += cant;
      total += cant;
    }
  }
  const serie = Object.keys(porProd).map(function (k) { return porProd[k]; });
  serie.sort(function (a, b) { return b.valor - a.valor || (a.etiqueta < b.etiqueta ? -1 : 1); });
  return {
    valor: total,
    unidad: 'unidades',
    serie: serie,
    nota: 'Suma unidades de pedidos confirmados, enviados, entregados o con novedad de los últimos 365 días.'
  };
}

