function calcular(datos) {
  const dia = (iso) => new Date(Date.parse(iso) - 5 * 3600 * 1000).toISOString().slice(0, 10);
  const N = 365;
  const hoyDia = dia(datos.hoy);
  const limiteDia = dia(new Date(Date.parse(datos.hoy) - N * 86400000).toISOString());
  const casos = (datos.tablas && datos.tablas.casos) || [];
  let sumaMs = 0;
  let n = 0;
  for (let i = 0; i < casos.length; i++) {
    const c = casos[i];
    if (!c || !c.creado || !c.resuelto) continue;
    if (c.estado !== "resuelto") continue;
    const dRes = dia(c.resuelto);
    if (!(dRes > limiteDia && dRes <= hoyDia)) continue;
    const t0 = Date.parse(c.creado);
    const t1 = Date.parse(c.resuelto);
    if (isNaN(t0) || isNaN(t1) || t1 < t0) continue;
    sumaMs += (t1 - t0);
    n++;
  }
  if (n === 0) {
    return { valor: 0, unidad: "horas", nota: "Sin casos resueltos en los últimos 365 días." };
  }
  const promedio = sumaMs / n / 3600000;
  const valor = Math.round(promedio * 10) / 10;
  return { valor: valor, unidad: "horas", nota: "Promedio sobre " + n + " casos resueltos en los últimos 365 días." };
}

