function fmtBogota(iso) { return new Date(Date.parse(iso) - 5 * 3600 * 1000).toISOString().slice(0, 16).replace("T", " "); }
function consultar(datos) {
  var dia = function (iso) { return new Date(Date.parse(iso) - 5 * 3600 * 1000).toISOString().slice(0, 10); };
  var fmt = function (iso) { return new Date(Date.parse(iso) - 5 * 3600 * 1000).toISOString().slice(0, 16).replace("T", " "); };
  var tablas = (datos && datos.tablas) || {};
  var pedidos = tablas.pedidos || [];
  var clientes = tablas.clientes || [];
  var mapaClientes = {};
  for (var i = 0; i < clientes.length; i++) {
    var c = clientes[i];
    if (c && c.id) mapaClientes[c.id] = c;
  }
  var hoyDia = dia(datos.hoy);
  var msHoy = Date.parse(hoyDia);
  var diaLimite365 = dia(new Date(Date.parse(datos.hoy) - 365 * 86400000).toISOString());
  var filas = [];
  for (var j = 0; j < pedidos.length; j++) {
    var p = pedidos[j];
    if (!p || p.estado !== "pendiente" || !p.creado) continue;
    var diaPedido = dia(p.creado);
    if (!(diaPedido > diaLimite365)) continue;
    var diasPendiente = Math.floor((msHoy - Date.parse(diaPedido)) / 86400000);
    if (!(diasPendiente > 3)) continue;
    var cli = mapaClientes[p.clienteId] || null;
    filas.push({
      numero: (p.numero !== undefined && p.numero !== null) ? p.numero : null,
      fecha_creacion: fmt(p.creado),
      dias_pendiente: diasPendiente,
      cliente: cli && cli.nombre ? cli.nombre : null,
      telefono: cli && cli.telefonoEnmascarado ? cli.telefonoEnmascarado : null,
      total: (p.total !== undefined && p.total !== null) ? p.total : null,
      ciudad: p.ciudad || null,
      estado: p.estado,
      _creado: p.creado
    });
  }
  filas.sort(function (a, b) { return Date.parse(b._creado) - Date.parse(a._creado); });
  var out = [];
  var n = filas.length > 200 ? 200 : filas.length;
  for (var k = 0; k < n; k++) {
    var f = filas[k];
    out.push({
      numero: f.numero,
      fecha_creacion: f.fecha_creacion,
      dias_pendiente: f.dias_pendiente,
      cliente: f.cliente,
      telefono: f.telefono,
      total: f.total,
      ciudad: f.ciudad,
      estado: f.estado
    });
  }
  return out;
}
